fn add_job(c:&Value,v:&str,b:usize,panel:&str,ids:&Value,base:&Value,jobs:&mut Vec<Value>,steps:&mut Vec<Value>){
 let name=if panel=="latency"{format!("b{b}-{}-{v}",c["name"].as_str().unwrap())}else{format!("{panel}-{}-{v}",c["name"].as_str().unwrap())};let(rounds,prime)=match panel{"preflight"=>(1,1),"cycles"=>(65536,256),_ =>(2048,256)};let workers=c["workers"].as_u64().unwrap();let affinity=if workers==1{"2".to_string()}else{format!("0-{}",workers-1)};let mut env=base.clone();env["RAYON_NUM_THREADS"]=json!("1");let mut argv=vec![];let mut data=None;
 if panel=="stat"||panel=="cycles"{env["ZOPRO_BENCH_PERF_CTL"]=json!(r("ctl"));env["ZOPRO_BENCH_PERF_ACK"]=json!(r("ack"));argv.extend(["sudo".into(),"-n".into(),"env".into()]);for(k,x)in env.as_object().unwrap(){argv.push(format!("{k}={}",x.as_str().unwrap()));}argv.push("perf".into());if panel=="stat"{let p=r("stat").join(format!("{name}.csv"));argv.extend(["stat".into(),"--no-big-num".into(),"-x".into(),";".into(),"-e".into(),"{cycles:u,instructions:u,cache-misses:u,branch-misses:u}".into(),"-o".into(),p.display().to_string()]);data=Some(p);}else{let p=r("perf").join(format!("{name}.data"));argv.extend(["record".into(),"--no-buildid-cache".into(),"--sample-cpu".into(),"--timestamp".into(),"-P".into(),"-e".into(),"cycles:u".into(),"-c".into(),"16000000".into(),"-m".into(),"512".into(),"-o".into(),p.display().to_string()]);data=Some(p);}argv.extend(["--delay=-1".into(),format!("--control=fifo:{},{}",r("ctl").display(),r("ack").display()),"--".into()]);}
 argv.extend(["taskset".into(),"-c".into(),affinity,ids[v]["binary"].as_str().unwrap().into(),c["file"].as_str().unwrap().into(),workers.to_string(),rounds.to_string(),prime.to_string()]);let mut s=step(&name,argv);if panel=="latency"||panel=="preflight"{s["environment"]=env;}steps.push(s);jobs.push(json!({"name":name,"case":c,"variant":v,"block":b,"panel":panel,"rounds":rounds,"prime":prime,"data":data,"binary":ids[v]["binary"]}));
}
