fn loss(data:&str){let mut child=Command::new("perf").args(["script","-D","-i",data]).stdout(Stdio::piped()).spawn().unwrap();let mut lost=vec![];let mut lines=0;for l in BufReader::new(child.stdout.take().unwrap()).lines(){let l=l.unwrap();lines+=1;if l.contains("PERF_RECORD_LOST"){lost.push(l);}}assert!(child.wait().unwrap().success());println!("{}",json!({"zero_lost":lost.is_empty(),"records":lost,"lines":lines}));}
fn interval(values:&[f64])->Value{assert_eq!(values.len(),31);let mut a=values.to_vec();a.sort_by(f64::total_cmp);json!({"median":a[15],"low":a[9],"high":a[21],"wins":values.iter().filter(|x|**x<1.).count(),"ratios":values,"conditional_nominal_coverage":0.9705506265163422})}
